// Parse metadata from filename or file content
// Gemini usually names the file: "Transcrição de <Meeting Title> - <Date>"
// Adjust this parser to match your actual filename pattern

const fileName = $('Google Drive Trigger').item.json.name || '';
const fileContent = $input.item.binary?.data 
  ? Buffer.from($input.item.binary.data, 'base64').toString('utf-8')
  : '';

// Try to extract info from filename
// Example: "Transcrição - João Silva + ACME Corp - 2024-01-15.txt"
let vendorName = 'Vendedor não identificado';
let prospectName = 'Prospect não identificado';
let company = 'Empresa não identificada';
let callDate = new Date().toISOString();
let duration = 60; // default 60 min

// Look for duration in transcript (HH:MM or Xh Ymin patterns)
const durationMatch = fileContent.match(/(\d+)h\s*(\d+)?\s*min/i) || fileContent.match(/Duração[:\s]+(\d+):(\d+)/i);
if (durationMatch) {
  duration = parseInt(durationMatch[1]) * 60 + parseInt(durationMatch[2] || '0');
}

// Extract date from filename if present
const dateMatch = fileName.match(/(\d{4}-\d{2}-\d{2})/);
if (dateMatch) {
  callDate = new Date(dateMatch[1]).toISOString();
}

// You can also embed metadata in the first lines of the transcript
// Format: "Vendedor: [name]" / "Prospect: [name]" / "Empresa: [name]"
const vendorMatch = fileContent.match(/Vendedor[:\s]+([^\n]+)/i);
const prospectMatch = fileContent.match(/Prospect[:\s]+([^\n]+)/i);
const companyMatch = fileContent.match(/Empresa[:\s]+([^\n]+)/i);
const dateMatch2 = fileContent.match(/Data[:\s]+([^\n]+)/i);

if (vendorMatch) vendorName = vendorMatch[1].trim();
if (prospectMatch) prospectName = prospectMatch[1].trim();
if (companyMatch) company = companyMatch[1].trim();
if (dateMatch2) {
  const parsed = new Date(dateMatch2[1].trim());
  if (!isNaN(parsed.getTime())) callDate = parsed.toISOString();
}

return {
  vendorName,
  prospectName,
  company,
  callDate,
  duration,
  fileName,
  transcriptUrl: `https://drive.google.com/file/d/${$('Google Drive Trigger').item.json.id}/view`,
  transcript: fileContent,
};

