// Parse the AI response JSON
const aiResponse = $input.item.json;
const content = aiResponse.content?.[0]?.text || aiResponse.choices?.[0]?.message?.content || '';

let analysis;
try {
  // Remove markdown code fences if present
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  analysis = JSON.parse(cleaned);
} catch (e) {
  // Try to extract JSON from the text
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    analysis = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Could not parse AI response: ' + content.substring(0, 200));
  }
}

// Validate and set defaults
analysis.score = Math.max(0, Math.min(100, Number(analysis.score) || 0));
analysis.strengths = Array.isArray(analysis.strengths) ? analysis.strengths : [];
analysis.improvements = Array.isArray(analysis.improvements) ? analysis.improvements : [];
analysis.nextSteps = Array.isArray(analysis.nextSteps) ? analysis.nextSteps : [];

// Validate methodology scores (0-10)
const meth = analysis.methodology || {};
['rapport', 'discovery', 'presentation', 'objectionHandling', 'closing'].forEach(k => {
  meth[k] = Math.max(0, Math.min(10, Number(meth[k]) || 0));
});
analysis.methodology = meth;

// Validate hubspot fields
analysis.hubspotFields = analysis.hubspotFields || {};

return { analysis };

// Log completion
const callId = $('Salvar Análise no App').item.json.id;
const score = $('Processar Resposta IA').item.json.analysis.score;
console.log(`✅ Call ${callId} processada com score ${score}`);
return { success: true, callId, score };
